WITH enriched AS (SELECT id, store_id, product_id, sale_date, units, revenue, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY units DESC, id) seq_no, SUM(units) OVER (PARTITION BY product_id ORDER BY units, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_units, RANK() OVER (PARTITION BY product_id, store_id ORDER BY units DESC NULLS LAST) units_rank FROM store_sales), cleaned AS (SELECT id, store_id, product_id, sale_date, units, revenue, seq_no, cumulative_units, CAST(units AS DOUBLE) units_str, seq_no * revenue seq_no_times_revenue FROM enriched WHERE sale_date > DATE '2023-04-08'), ranked AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY product_id ORDER BY seq_no DESC NULLS LAST) AS dedup_rank FROM cleaned) t WHERE dedup_rank = 1), with_dims AS (SELECT s.*, p.price, p.cost, p.category FROM ranked s LEFT JOIN products p ON s.product_id = p.id), with_dims_store_sales AS (SELECT a.*, p.opened_date FROM with_dims a LEFT JOIN stores p ON a.store_id = p.id), scored AS (SELECT *, FIRST_VALUE(cost) IGNORE NULLS OVER (PARTITION BY store_id ORDER BY seq_no_times_revenue, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_cost, ROW_NUMBER() OVER (PARTITION BY product_id, category ORDER BY price DESC, id) event_seq, MIN(units) OVER (PARTITION BY store_id) store_id_min_units FROM with_dims_store_sales), with_dims_store_sales_2 AS (SELECT s.*, d.sqft, d.opened_date AS store_opened_date FROM scored s JOIN stores d ON s.store_id = d.id) SELECT id, store_id, product_id, units, seq_no, cumulative_units, units_str, cost, event_seq FROM with_dims_store_sales_2
